import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { sendChatMessage } from '../redux/slices/chatSlice';
import './TherapyChat.css';
import api from '../services/api';

const TherapyChat = () => {
  const [messages, setMessages] = useState([
    { role: 'assistant', content: "Hello! I'm your mindfulness therapy assistant. How are you feeling today?" }
  ]);
  const [newMessage, setNewMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [sessionId, setSessionId] = useState(null);
  const [error, setError] = useState(null);

  const handleSendMessage = async (e) => {
    e.preventDefault();
    
    if (!newMessage.trim()) return;
    
    // Add user message to UI immediately
    const userMessage = { role: 'user', content: newMessage };
    const updatedMessages = [...messages, userMessage];
    setMessages(updatedMessages);
    setNewMessage('');
    setIsLoading(true);
    setError(null);
    
    try {
      // Call the backend API
      const response = await api.post('/api/therapy/chat', {
        message: newMessage,
        chat_session_id: sessionId
      });
      
      // Add assistant response
      const assistantMessage = { 
        role: 'assistant', 
        content: response.data.response
      };
      
      setMessages([...updatedMessages, assistantMessage]);
      
      // If this is a new session, store the session ID
      if (!sessionId && response.data.chat_session_id) {
        setSessionId(response.data.chat_session_id);
      }
      
    } catch (err) {
      console.error('Error sending message:', err);
      setError('Failed to get a response. Please try again.');
      
      // Add error message to chat
      setMessages([
        ...updatedMessages,
        { 
          role: 'assistant', 
          content: "I'm having trouble connecting to my therapy assistant right now. Please try again in a moment."
        }
      ]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="therapy-chat-page">
      <div className="container">
        <div className="chat-container">
          <div className="chat-header">
            <h1>Therapy Chat</h1>
            {error && <div className="error-banner">{error}</div>}
          </div>
          
          <div className="chat-messages">
            {messages.map((message, index) => (
              <div key={index} className={`message message-${message.role}`}>
                {message.content}
              </div>
            ))}
            
            {isLoading && (
              <div className="message message-assistant loading">
                <div className="loading-dots">
                  <span></span>
                  <span></span>
                  <span></span>
                </div>
              </div>
            )}
          </div>
          
          <form className="chat-input-form" onSubmit={handleSendMessage}>
            <input
              type="text"
              placeholder="Type your message..."
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              disabled={isLoading}
            />
            <button 
              type="submit" 
              className="btn btn-primary"
              disabled={isLoading || !newMessage.trim()}
            >
              Send
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default TherapyChat;
